import JSZip from 'jszip';

export interface VirtualFile {
  path: string;
  content: string;
  package: 'core' | 'theme' | 'docs';
  language: 'php' | 'css' | 'js' | 'javascript' | 'json' | 'markdown' | 'svg' | 'txt';
  updatedAt: string;
}

export type WpVirtualFile = VirtualFile;

